    sp_faq_tag: 'Frequently asked questions',
    sp_faq_title_1: 'What people',
    sp_faq_title_2: 'ask us most',
    sp_faq_q1: 'How do I access my product?',
    sp_faq_a1: 'After completing your purchase with Stripe, you\'ll receive a confirmation email. Log in to the portal with your email and password, and your product will be immediately available in the "My Portal" section.',
    sp_faq_q2: 'Can I get a refund?',
    sp_faq_a2: 'Yes, we offer a 30-day guarantee. If you\'re not satisfied with your purchase, write to us at admin@yayika.com and we\'ll refund 100% of your money with no questions.',
    sp_faq_q3: 'How does the membership work?',
    sp_faq_a3: 'The membership gives you unlimited access to all products, the interactive portal, women\'s circles and new releases. You can choose between Semilla, Guerrera or Diamante plans.',
    sp_faq_q4: 'Can I cancel my membership?',
    sp_faq_a4: 'Yes, you can cancel at any time from your portal. There\'s no commitment or penalties. Your access will continue until the end of the paid period.',
    sp_faq_q5: 'Do the products work on mobile?',
    sp_faq_a5: 'Yes! Yayika is a Progressive Web App (PWA) that works from your phone\'s browser. You can also install it as an app from Chrome â†’ Menu â‹® â†’ "Add to home screen".',
    sp_faq_q6: 'How do I join the affiliate program?',
    sp_faq_a6: 'Visit our affiliate page to register. You get a personalized code and earn commissions on every sale you generate with your link.',
    sp_faq_q7: 'What languages is it available in?',
    sp_faq_a7: 'Yayika is available in Spanish, English, Portuguese, French and German. You can change the language from the selector at the top of the site.',
    sp_form_sending: 'Sending...',
