    modulo5_l1_p_1: 'You don\'t need $100,000 to invest. You can start with $100/month. What matters is starting, not the amount.',
    modulo5_l1_p_2: 'Index funds are like a basket of stocks. You buy a little of many companies at once. It\'s the simplest and least risky investment to start with.',
