    modulo3_l1_h2_negociar: 'Negotiating is communicating your value',
    modulo3_l1_p_negociar_1: 'Negotiating isn\'t confronting â€” it\'s communicating your value clearly and confidently. Women negotiate less than men, and when they do, they ask for less.',
